T = TypeVar("T")


class Job:
    def __init__(
        self,
        name: str,
        fn: Callable[..., T],
        interval_seconds: float,
        args: Optional[Tuple[Any, ...]] = None,
        kwargs: Optional[Dict[str, Any]] = None,
    ) -> None:
